UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"


def fetch(url, limit=None):
    h = {"User-Agent": UA, "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8", "Accept-Encoding": "gzip"}
    req = urllib.request.Request(url, headers=h)
    r = urllib.request.urlopen(req, timeout=45)
    raw = r.read()
    if r.headers.get("Content-Encoding") == "gzip":
        try:
            raw = gzip.decompress(raw)
        except Exception:
            pass
    for enc in ("utf-8", "gb18030", "gbk"):
        try:
            return raw.decode(enc), r.geturl()
        except Exception:
            pass
    return raw.decode("utf-8", "ignore"), r.geturl()


def to_text(t):
    t = re.sub(r"(?is)<(script|style|noscript|svg)[^>]*>.*?</\1>", " ", t)
    t = re.sub(r"(?is)<br\s*/?>", "\n", t)
    t = re.sub(r"(?is)</(p|div|li|h1|h2|h3|h4|h5|tr|td|dt|dd|section|article)>", "\n", t)
    t = re.sub(r"(?is)<[^>]+>", " ", t)
    t = htmllib.unescape(t)
    out = []
    for line in t.split("\n"):
        line = re.sub(r"[ \t\r\u00a0\u3000]+", " ", line).strip()
        if len(line) >= 2:
            out.append(line)
    return "\n".join(out)


def anchors(t):
    res = []
    for m in re.finditer(r'(?is)<a\b[^>]*href="([^"]+)"[^>]*>(.*?)</a>', t):
        href = htmllib.unescape(m.group(1))
        txt = re.sub(r"(?s)<[^>]+>", " ", m.group(2))
        txt = re.sub(r"\s+", " ", htmllib.unescape(txt)).strip()
        if txt and href:
            res.append((txt, href))
    return res


def resolve(href):
    if href.startswith("/link?") or href.startswith("http://www.sogou.com/link?") or href.startswith("https://www.sogou.com/link?"):
        u = "https://www.sogou.com" + href if href.startswith("/") else href
        try:
            _, final = fetch(u)
            return u + "  ->  " + final
        except Exception as e:
            return u + "  ->  ERROR %r" % (e,)
    return href


def main():
    mode = sys.argv[1]
    arg = sys.argv[2]
    out = sys.argv[3] if len(sys.argv) > 3 else None
    resolved = len(sys.argv) > 4 and sys.argv[4] == "resolve"
    if mode == "url":
