            "search_sogou": "https://www.sogou.com/web?query=" + urllib.parse.quote(q),
            "search_so": "https://www.so.com/s?q=" + urllib.parse.quote(q),
            "search_baidu": "https://www.baidu.com/s?wd=" + urllib.parse.quote(q),
            "search_bing": "https://cn.bing.com/search?q=" + urllib.parse.quote(q) + "&count=30",
            "search_weixin": "https://weixin.sogou.com/weixin?type=2&ie=utf8&query=" + urllib.parse.quote(q),
        }
        url = urls[mode]
