            i = txt.find(m)
            if i > 400:
                cut = min(cut, i)
        body = "FINAL: " + final + "\n" + txt[:cut]
        seen = set()
        lines = []
        for x, h in anchors(page):
            if h.startswith("javascript") or len(x) < 8:
                continue
            if "sogou.com/web" in h or "weixin.sogou.com" in h or "sogou.com/sogou" in h:
                continue
            key = x[:40]
            if key in seen:
                continue
            seen.add(key)
            if resolved and "/link?" in h:
                h = resolve(h)
            lines.append(x + "  ||  " + h)
        tail = "\n\n===== LINKS =====\n" + "\n".join(lines[:60])
    text = body + tail
    if out:
        open(out, "w", encoding="utf-8").write(text)
        print("written", out, len(text))
    else:
        sys.stdout.buffer.write(text.encode("utf-8"))


main()
