{"content": "import sys, re, gzip, time, html as htmllib, urllib.request, urllib.parse, http.cookiejar

UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
CJ = http.cookiejar.CookieJar()
OP = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(CJ))
OP.addheaders = [("User-Agent", UA), ("Accept-Language", "zh-CN,zh;q=0.9,en;q=0.8"),
                 ("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"),
                 ("Accept-Encoding", "gzip")]


def fetch(url, ref=None, tries=3):
    last = None
    for i in range(tries):
        try:
            req = urllib.request.Request(url)
            if ref:
                req.add_header("Referer", ref)
            r = OP.open(req, timeout=45)
            raw = r.read()
            if r.headers.get("Content-Encoding") == "gzip":
                try:
                    raw = gzip.decompress(raw)
                except Exception:
                    pass
            for enc in ("utf-8", "gb18030", "gbk"):
                try:
                    return raw.decode(enc), r.geturl()
                except Exception:
                    pass
            return raw.decode("utf-8", "ignore"), r.geturl()
        except Exception as e:
            last = e
            time.sleep(3 * (i + 1))
    raise last


def to_text(t):
    t = re.sub(r"(?is)<(script|style|noscript|svg)[^>]*>.*?</\1>", " ", t)
    t = re.sub(r"(?is)<br\s*/?>", "\n", t)
    t = re.sub(r"(?is)</(p|div|li|h1|h2|h3|h4|h5|tr|td|dt|dd|section|article)>", "\n", t)
    t = re.sub(r"(?is)<[^>]+>", " ", t)
    t = htmllib.unescape(t)
    out = []
    for line in t.split("\n"):
        line = re.sub(r"[ \t\r\u00a0\u3000]+", " ", line).strip()
        if len(line) >= 2:
            out.append(line)
    return "\n".join(out)


def anchors(t):
    res = []
    for m in re.finditer(r'(?is)<a\b[^>]*href="([^"]+)"[^>]*>(.*?)</a>', t):
        href = htmllib.unescape(m.group(1))
        txt = re.sub(r"(?s)<[^>]+>", " ", m.group(2))
        txt = re.sub(r"\s+", " ", htmllib.unescape(txt)).strip()
        if txt and href:
            res.append((txt, href))
    return res


def is_block(page, final):
    return "antispider" in final or "验证码" in page[:600] or "captcha" in final.lower()


def sogou(q):
    return "https://www.sogou.com/web?query=" + urllib.parse.quote(q)


def so(q):
    return "https://www.so.com/s?q=" + urllib.parse.quote(q)


def weixin(q):
    return "https://weixin.sogou.com/weixin?type=2&ie=utf8&query=" + urllib.parse.quote(q)


def run(cfg):
    label, engine, q = cfg
    if engine == "weixin":
        url = weixin(q)
    else:
        url = sogou(q)
    page, final = fetch(url, ref="https://www.sogou.com/")
    if is_block(page, final):
        page, final = fetch(so(q), ref="https://www.so.com/")
        engine = "so"
    txt = to_text(page)
    cut = len(txt)
    for m in ("旅程已至此", "相关搜索", "上5休1上5休3", "意见反馈及投诉", "版权所有", "大家还在搜"):
        i = txt.find(m)
        if i > 400:
            cut = min(cut, i)
    lines = []
    seen = set()
    for x, h in anchors(page):
        if h.startswith("javascript") or len(x) < 8:
            continue
        if "sogou.com/web" in h or "sogou.com/sogou" in h or "weixin.sogou.com/b" in h:
            continue
        if h.startswith("?") or h.startswith("/web?"):
            continue
        key = x[:40]
        if key in seen:
            continue
        seen.add(key)
        lines.append(x + "  ||  " + h)
    text = "ENGINE: %s\nFINAL: %s\n%s\n\n===== LINKS =====\n%s" % (engine, final, txt[:cut], "\n".join(lines[:70]))
    open("out_%s.txt" % label, "w", encoding="utf-8").write(text)
    print("written out_%s.txt [%s] %d" % (label, engine, len(text)))


# warm up
try:
    fetch("https://www.sogou.com/")
except Exception as e:
    print("warmup fail", repr(e))

for line in open(sys.argv[1], encoding="utf-8"):
    line = line.rstrip("\n")
    if not line.strip():
        continue
    parts = line.split("\t", 2)
    if len(parts) < 3:
        parts = [parts[0], "sogou", parts[1]]
    try:
        run(parts)
    except Exception as e:
        print("FAIL", parts[0], repr(e))
    time.sleep(6)
